import test from 'node:test';import assert from 'node:assert/strict';import {createBoardFlow} from '../src/pixi/board-flow.js';
test('combined components admit in their own phases and keep accepted locations',()=>{const {flow,setMode}=createBoardFlow();flow.start();const advance=n=>{for(let i=0;i<n*120;i++)flow.step(1/120);};setMode('normal');advance(12);assert.equal(flow.counts.rush,0);assert.equal(flow.counts.bonus,0);assert.ok(flow.counts.start>0);setMode('rush');advance(12);assert.ok(flow.counts.rush>0);assert.equal(flow.counts.bonus,0);const rush=flow.counts.rush;setMode('bonus');advance(12);assert.ok(flow.counts.bonus>0);assert.equal(flow.counts.rush,rush);assert.equal(flow.physics.pockets.find(p=>p.kind==='rush').x,359.5);assert.equal(flow.physics.pockets.find(p=>p.kind==='bonus').x,357.25);const guide=flow.physics.colliders.find(c=>c.role==='right-inner-lower');assert.equal(guide.a.x,336);assert.equal(guide.b.x,330);});
test('combined closed chutes release launched balls after drain',()=>{const {flow,setMode}=createBoardFlow();setMode('normal');flow.start();for(let i=0;i<40*120;i++)flow.step(1/120);flow.stop();for(let i=0;i<35*120;i++)flow.step(1/120);assert.equal(flow.physics.balls.length,0);assert.equal(flow.counts.bonus,0);assert.equal(flow.counts.rush,0);});
